sys_ux_data_broker_transform.script:
function transform(input) {
    var sysPropertyName = "sam.foundation.current.businessunit.kpi"; 
    var totalKpiCount = 0;
    var totalRecords = 0;
    var duplicateCount = 0; 

    // Get system property value
    var sysPropertyValue = gs.getProperty(sysPropertyName);

    if (!sysPropertyValue) {
        gs.log("No system property value found for: " + sysPropertyName);
    } else {
        try {
            var config = JSON.parse(sysPropertyValue);
            var kpisArray = Array.isArray(config) ? config : config.kpis;

            // Get total record count (either from config or default "cmn_location")
            var totalRecordsTable = config.totalRecordsTable || "cmn_location";
            gs.log("Fetching total records from table: " + totalRecordsTable);

            var recordCount = new GlideAggregate(totalRecordsTable);
            recordCount.addAggregate('COUNT');
            recordCount.query();

            if (recordCount.next()) {
                totalRecords = parseInt(recordCount.getAggregate('COUNT'), 10);
                gs.log("Total records found: " + totalRecords);
            } else {
                gs.log("No records found in table: " + totalRecordsTable);
            }

            // Process KPI queries
            if (Array.isArray(kpisArray)) {
                gs.log("Processing KPI queries...");

                kpisArray.forEach(function (kpi, index) {
                    gs.log("Processing KPI #" + index + " - KPI Name: " + kpi.kpi);

                    if (!kpi.table) {
                        gs.log("Skipping KPI #" + index + " - Missing table name.");
                        return;
                    }

                    var kpiQuery = new GlideAggregate(kpi.table);
                    kpiQuery.addAggregate('COUNT');

                    // Apply filtering condition
                    if (kpi.field !== 'name') {
                        gs.log("Applying condition: " + kpi.field);
                        kpiQuery.addEncodedQuery(kpi.field);
                    } else if (kpi.field === 'name') {
                        gs.log('Checking for duplicate business units...');
                        kpiQuery.addAggregate('COUNT', 'name');
                        kpiQuery.groupBy("name");
                        kpiQuery.addHaving("COUNT", ">", 1);
                    }

                    kpiQuery.query();

                    while (kpiQuery.next()) {
                        if (kpi.field !== 'name') {
                            var kpiCount = parseInt(kpiQuery.getAggregate('COUNT'), 10);
                            totalKpiCount += kpiCount;
                            gs.log("KPI #" + index + " - Count: " + kpiCount);
                        } else if (kpi.field === 'name') {
                            var duplicateValue = kpiQuery.getValue('name');
                            var count = parseInt(kpiQuery.getAggregate('COUNT', 'name'), 10);

                            gs.info('Duplicate Record Found: ' + duplicateValue + ' - Count: ' + count);
                            duplicateCount++;
                        }
                    }
                });

                totalKpiCount += duplicateCount; 
                gs.log("Total KPI matching records (excluding duplicates): " + (totalKpiCount - duplicateCount));
                gs.log("Total Duplicate Count: " + duplicateCount);
                gs.log("Total KPI matching records (including duplicates): " + totalKpiCount);
            } else {
                gs.log("No valid KPI configurations found.");
            }

            gs.log("Total record count: " + totalRecords);

            // Calculate percentage
            var percentage = (totalRecords > 0) ? (totalKpiCount / totalRecords) * 100 : 0;
            gs.log("Final KPI Percentage: " + percentage.toFixed(2) + "%");
            return { output: percentage.toFixed(2) + "%" };

        } catch (e) {
            gs.error("Error in KPI calculation: " + e.message);
        }
    }
}

transform("!");
